from taf.ul.sc.perf.tc import tc


_test_status = 'DB->enumerated properties->status'
_logs_url = 'DB->string properties->logs url'
_validation_url = 'DB->string properties->validation url'
_test_id = 'DB->id'


def add_test_status(test_status):
    tc.add_stats(stats={_test_status: test_status})


def add_url_logs_link(url_log_link):
    tc.add_stats(stats={_logs_url: url_log_link})


def add_teb_execution_id(execution_id):
    tc.add_stats(stats={_test_id: execution_id})


def add_url_validation_link(url_validation_link):
    tc.add_stats(stats={_validation_url: url_validation_link})
